  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, title: 'Study OS',
    themeMode: dark ? ThemeMode.dark : ThemeMode.light,
    theme: ThemeData(useMaterial3: true,colorSchemeSeed: const Color(0xFF625BFF),brightness: Brightness.light),
    darkTheme: ThemeData(useMaterial3: true,colorSchemeSeed: const Color(0xFF817AFF),brightness: Brightness.dark,scaffoldBackgroundColor: const Color(0xFF0D0F17)),
    home: Scaffold(
      body: [Home(store: widget.store,onTheme: () async {setState(()=>dark=!dark);await widget.store.setDarkMode(dark);}),
        StudyHub(store: widget.store,onRefresh: refresh), ProgressScreen(store: widget.store), const ProfileScreen()][tab],
      bottomNavigationBar: NavigationBar(selectedIndex: tab,onDestinationSelected: (i)=>setState(()=>tab=i),destinations: const [
        NavigationDestination(icon: Icon(Icons.home_outlined),selectedIcon: Icon(Icons.home_rounded),label: 'Home'),
        NavigationDestination(icon: Icon(Icons.menu_book_outlined),selectedIcon: Icon(Icons.menu_book_rounded),label: 'Study'),
        NavigationDestination(icon: Icon(Icons.insights_outlined),selectedIcon: Icon(Icons.insights_rounded),label: 'Progress'),
        NavigationDestination(icon: Icon(Icons.person_outline_rounded),selectedIcon: Icon(Icons.person_rounded),label: 'Profile'),
      ]),
    ),
  );
}

