class _AllocationState extends State<Allocation>{late List<int> values;late List<List<String>> topicNames;late List<TextEditingController> topicInputs;@override void initState(){super.initState();values=List.filled(widget.subjects.length,0);topicNames=List.generate(widget.subjects.length,(_)=>[]);topicInputs=List.generate(widget.subjects.length,(_)=>TextEditingController());}int get used=>values.fold(0,(a,b)=>a+b);void addTopic(int i){final t=topicInputs[i].text.trim();if(t.isNotEmpty&&!topicNames[i].contains(t))setState((){topicNames[i].add(t);topicInputs[i].clear();});}@override void dispose(){for(final c in topicInputs)c.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Topics & time allocation')),body:ListView(padding:const EdgeInsets.all(20),children:[Card(child:Padding(padding:const EdgeInsets.all(18),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('Allocated: $used min',style:const TextStyle(fontWeight:FontWeight.w800)),Text('Remaining: ${widget.total-used} min',style:const TextStyle(fontWeight:FontWeight.w800))]))),const SizedBox(height:12),...widget.subjects.asMap().entries.map((e){final i=e.key;return Card(child:Padding(padding:const EdgeInsets.fromLTRB(16,10,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[ListTile(contentPadding:EdgeInsets.zero,title:Text(e.value,style:const TextStyle(fontWeight:FontWeight.w800)),trailing:Text('${values[i]}m')),Slider(value:values[i].toDouble(),min:0,max:widget.total.toDouble(),divisions:widget.total,onChanged:(v){final other=used-values[i];setState(()=>values[i]=v.round().clamp(0,widget.total-other));}),const SizedBox(height:4),Text('Topics / chapters',style:Theme.of(context).textTheme.labelLarge),const SizedBox(height:6),Row(children:[Expanded(child:TextField(controller:topicInputs[i],onSubmitted:(_)=>addTopic(i),decoration:const InputDecoration(hintText:'e.g. Quadratic Equations',border:OutlineInputBorder(),isDense:true))),const SizedBox(width:8),IconButton.filled(onPressed:()=>addTopic(i),icon:const Icon(Icons.add))]),if(topicNames[i].isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Wrap(spacing:8,runSpacing:8,children:topicNames[i].map((t)=>InputChip(label:Text(t),onDeleted:()=>setState(()=>topicNames[i].remove(t))).toList())))]));}),const SizedBox(height:24),FilledButton.icon(onPressed:used==0?null:(){final items=<StudyItem>[];for(var i=0;i<widget.subjects.length;i++){if(values[i]<=0)continue;final names=topicNames[i];if(names.isEmpty){items.add(StudyItem(title:widget.subjects[i],minutes:values[i],topic:'Study block'));}else{final base=values[i]~/names.length;var remainder=values[i]%names.length;for(final name in names){final m=base+(remainder>0?1:0);remainder--;if(m>0)items.add(StudyItem(title:widget.subjects[i],minutes:m,topic:name));}}}final plan=StudyPlan(totalMinutes:widget.total,items:items);widget.store.savePlan(plan);Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>FocusScreen(store:widget.store,plan:plan,index:0,blockIndex:0)));},icon:const Icon(Icons.play_arrow),label:const Padding(padding:EdgeInsets.all(14),child:Text('Save plan & start')))]));}}

